    std::string Host_Web_Emscripten::getNavigatorLocale()
    {
        char* raw = (char*)EM_ASM_PTR({
            var lang = window.navigator.language || "en-US";
            var len = lengthBytesUTF8(lang) + 1;
            var buf = _malloc(len);
            stringToUTF8(lang, buf, len);
            return buf;
        });
        std::string result(raw);
        free(raw);
        return result;
    }
